# Joins Code.gs, Logic.gs and Data.gs into dist/RestockBot.gs, the one file
# to paste into the Apps Script project. Run from the repo root:
# python3 restock-bot/tools/build.py
import os
os.makedirs('restock-bot/dist', exist_ok=True)
parts = [open(f'restock-bot/{n}.gs', encoding='utf-8').read() for n in ('Code', 'Logic', 'Data')]
open('restock-bot/dist/RestockBot.gs', 'w', encoding='utf-8').write(
    '// Time Planet restock bot. Generated by restock-bot/tools/build.py from Code.gs, Logic.gs and Data.gs.\n'
    '// Paste this whole file into the Apps Script project, then run start().\n\n' + '\n\n'.join(parts))
print('restock-bot/dist/RestockBot.gs', sum(map(len, parts)), 'chars')
